        </div>
        <a
          href="https://github.com/PostHog/posthog"
          target="_blank"
          rel="noreferrer"
          className="shrink-0 text-xs opacity-40 hover:opacity-70 transition-opacity mt-1"
        >
          posthog/posthog ↗
        </a>
      </div>

      <div className="flex flex-col gap-3">
        {top5.map((eng, i) => (
          <EngineerCard key={eng.login} eng={eng} rank={i} />
        ))}
      </div>

      <MethodologyPanel />

      <footer className="text-center text-xs opacity-30 pb-2">
        Scored with the{" "}
        <a
          href="https://queue.acm.org/detail.cfm?id=3454124"
          target="_blank"
          rel="noreferrer"
          className="underline"
        >
          SPACE framework
        </a>{" "}
        · Data fetched {fetched.toLocaleDateString()}
      </footer>
    </div>
  );
}

