1	import rawData from "./data/github-data.json";
2	
3	// --- Types ---
4	
5	interface Review {
6	  reviewer: string;
7	  state: string;
8	  submittedAt: string;
9	}
10	
11	interface PRDetail {
12	  number: number;
13	  author: string;
14	  authorAvatar: string;
15	  title: string;
16	  mergedAt: string;
17	  createdAt: string;
18	  additions: number;
19	  deletions: number;
20	  changedFiles: number;
21	  labels: string[];
22	  reviews: Review[];
23	  reviewCommentCount: number;
24	  requestChangesCount: number;
25	}
26	
27	export interface EngineerMetrics {
28	  login: string;
29	  avatarUrl: string;
30	
31	  // Raw metrics (shown in UI for transparency)
32	  prsAuthored: number;
33	  prsReviewed: number;
34	  uniqueAuthorsReviewed: number;
35	  reviewCommentsGiven: number;
36	  medianCycleTimeHours: number;   // open → merge
37	  medianReviewTurnaroundHours: number; // pr open → first review from this person
38	  cleanMergeRate: number;         // % of own PRs with zero CHANGES_REQUESTED
39	  weeklyConsistency: number;      // 0–1, fraction of active weeks with at least one contribution
40	
41	  // Normalized SPACE dimension scores (0–100)
42	  scores: {
43	    satisfaction: number;
44	    performance: number;
45	    activity: number;
46	    collaboration: number;
47	    efficiency: number;
48	    composite: number;
49	  };
50	}
51	
52	// --- Helpers ---
53	
54	function median(values: number[]): number {
55	  if (values.length === 0) return 0;
56	  const sorted = [...values].sort((a, b) => a - b);
57	  const mid = Math.floor(sorted.length / 2);
58	  return sorted.length % 2 === 0
59	    ? (sorted[mid - 1] + sorted[mid]) / 2
60	    : sorted[mid];
61	}
62	
63	function hoursBetween(a: string, b: string): number {
64	  return (new Date(b).getTime() - new Date(a).getTime()) / 3_600_000;
65	}
66	
67	// Min-max normalize an array to 0–100. Higher raw = better unless `invert` is true.
