import rawData from "./data/github-data.json";

// --- Types ---

interface Review {
  reviewer: string;
  state: string;
  submittedAt: string;
}

interface PRDetail {
  number: number;
  author: string;
  authorAvatar: string;
  title: string;
  mergedAt: string;
  createdAt: string;
  additions: number;
  deletions: number;
  changedFiles: number;
  labels: string[];
  reviews: Review[];
  reviewCommentCount: number;
  requestChangesCount: number;
}

export interface EngineerMetrics {
  login: string;
  avatarUrl: string;

  // Raw metrics (shown in UI for transparency)
  prsAuthored: number;
  prsReviewed: number;
  uniqueAuthorsReviewed: number;
  reviewCommentsGiven: number;
  medianCycleTimeHours: number;   // open → merge
  medianReviewTurnaroundHours: number; // pr open → first review from this person
  cleanMergeRate: number;         // % of own PRs with zero CHANGES_REQUESTED
  weeklyConsistency: number;      // 0–1, fraction of active weeks with at least one contribution

  // Normalized SPACE dimension scores (0–100)
  scores: {
    satisfaction: number;
    performance: number;
    activity: number;
    collaboration: number;
    efficiency: number;
    composite: number;
  };
}

// --- Helpers ---

function median(values: number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 0
    ? (sorted[mid - 1] + sorted[mid]) / 2
    : sorted[mid];
}

function hoursBetween(a: string, b: string): number {
  return (new Date(b).getTime() - new Date(a).getTime()) / 3_600_000;
}

// Min-max normalize an array to 0–100. Higher raw = better unless `invert` is true.
function normalize(values: number[], invert = false): number[] {
  const min = Math.min(...values);
  const max = Math.max(...values);
  if (max === min) return values.map(() => 50);
  return values.map((v) => {
    const norm = ((v - min) / (max - min)) * 100;
    return invert ? 100 - norm : norm;
  });
}

// --- Main scoring function ---

export function computeRankings(): EngineerMetrics[] {
  const prs = rawData.prDetails as PRDetail[];

  // Index PRs reviewed by each engineer
  const reviewedPRs: Record<string, PRDetail[]> = {};
  for (const pr of prs) {
    for (const review of pr.reviews) {
      if (!reviewedPRs[review.reviewer]) reviewedPRs[review.reviewer] = [];
      reviewedPRs[review.reviewer].push(pr);
    }
  }

  // All active engineers = union of authors and reviewers
  const allLogins = new Set([
    ...prs.map((p) => p.author),
    ...Object.keys(reviewedPRs),
  ]);

  // Avatar map from authored PRs
  const avatarMap: Record<string, string> = {};
  for (const pr of prs) avatarMap[pr.author] = pr.authorAvatar;

  // Determine week buckets for consistency scoring
  const since = new Date(rawData.since);
  const now = new Date(rawData.fetchedAt);
  const totalWeeks = Math.ceil(
    (now.getTime() - since.getTime()) / (7 * 24 * 3_600_000)
  );

  const rawMetrics: Omit<EngineerMetrics, "scores">[] = [];

  for (const login of allLogins) {
    const authored = prs.filter((p) => p.author === login);
    const reviewed = reviewedPRs[login] ?? [];

    // Activity
    const prsAuthored = authored.length;
    const prsReviewed = reviewed.length;

    // Collaboration
    const uniqueAuthorsReviewed = new Set(reviewed.map((p) => p.author)).size;
    // Count review comments this engineer left (approximated as reviewCommentCount on PRs they reviewed)
    // We don't have per-reviewer comment counts from the API, so use review count as proxy
    const reviewCommentsGiven = reviewed.reduce((sum, pr) => {
      const theirReviews = pr.reviews.filter((r) => r.reviewer === login);
      return sum + theirReviews.length; // each submitted review = engagement unit
    }, 0);

    // Efficiency — cycle time for authored PRs
    const cycleTimes = authored.map((p) =>
      hoursBetween(p.createdAt, p.mergedAt)
    );
    const medianCycleTimeHours = median(cycleTimes);

    // Efficiency — review turnaround (how fast they review others' PRs)
    const turnaroundTimes: number[] = [];
    for (const pr of reviewed) {
      const theirReview = pr.reviews.find((r) => r.reviewer === login);
      if (theirReview?.submittedAt) {
        const hours = hoursBetween(pr.createdAt, theirReview.submittedAt);
        if (hours >= 0) turnaroundTimes.push(hours);
      }
    }
    const medianReviewTurnaroundHours = median(turnaroundTimes);

    // Performance — clean merge rate (own PRs with no CHANGES_REQUESTED)
    const cleanMergeRate =
      prsAuthored === 0
        ? 0
        : authored.filter((p) => p.requestChangesCount === 0).length /
          prsAuthored;

    // Satisfaction proxy — consistency across weeks (fraction of weeks active)
    const activeWeeks = new Set<number>();
    for (const pr of authored) {
      const week = Math.floor(
        (new Date(pr.mergedAt).getTime() - since.getTime()) /
          (7 * 24 * 3_600_000)
      );
      activeWeeks.add(week);
    }
    for (const pr of reviewed) {
      const review = pr.reviews.find((r) => r.reviewer === login);
      if (review?.submittedAt) {
        const week = Math.floor(
          (new Date(review.submittedAt).getTime() - since.getTime()) /
            (7 * 24 * 3_600_000)
        );
        activeWeeks.add(week);
      }
    }
    const weeklyConsistency = activeWeeks.size / totalWeeks;

    rawMetrics.push({
      login,
      avatarUrl: avatarMap[login] ?? `https://github.com/${login}.png`,
      prsAuthored,
      prsReviewed,
      uniqueAuthorsReviewed,
      reviewCommentsGiven,
      medianCycleTimeHours,
      medianReviewTurnaroundHours,
      cleanMergeRate,
      weeklyConsistency,
    });
  }

  // --- Normalize each metric across the pool ---

  const get = <K extends keyof Omit<EngineerMetrics, "scores" | "login" | "avatarUrl">>(
    key: K
  ) => rawMetrics.map((m) => m[key] as number);

  const normActivity = normalize(
    rawMetrics.map((m) => m.prsAuthored + m.prsReviewed)
  );
  const normPerformance = normalize(get("cleanMergeRate"));
  const normCollaboration = normalize(
    rawMetrics.map((m) => m.uniqueAuthorsReviewed + m.reviewCommentsGiven * 0.5)
  );
  // Lower cycle time = better → invert
  const normEfficiencyCycle = normalize(get("medianCycleTimeHours"), true);
  // Lower turnaround = better → invert (treat 0 as no reviews, penalize)
  const turnarounds = get("medianReviewTurnaroundHours").map((v, i) =>
    rawMetrics[i].prsReviewed === 0 ? Infinity : v
  );
  const normEfficiencyTurnaround = normalize(
    turnarounds.map((v) => (v === Infinity ? 0 : v)),
    true
  );
  const normEfficiency = normEfficiencyCycle.map(
    (v, i) => (v + normEfficiencyTurnaround[i]) / 2
  );
  const normSatisfaction = normalize(get("weeklyConsistency"));

  // Composite: equal weight across 5 dimensions
  const results: EngineerMetrics[] = rawMetrics.map((m, i) => ({
    ...m,
    scores: {
      satisfaction: Math.round(normSatisfaction[i]),
      performance: Math.round(normPerformance[i]),
      activity: Math.round(normActivity[i]),
      collaboration: Math.round(normCollaboration[i]),
      efficiency: Math.round(normEfficiency[i]),
      composite: Math.round(
        (normSatisfaction[i] +
          normPerformance[i] +
          normActivity[i] +
          normCollaboration[i] +
          normEfficiency[i]) /
          5
      ),
    },
  }));

  return results
    .sort((a, b) => b.scores.composite - a.scores.composite)
    .slice(0, 5);
}

