58	    }, 0);
59	
60	    const cycleTimes = authored.map((p) => hoursBetween(p.createdAt, p.mergedAt));
61	    const medianCycleTimeHours = median(cycleTimes);
62	
63	    const turnaroundTimes: number[] = [];
64	    for (const pr of reviewed) {
65	      const theirReview = pr.reviews.find((r) => r.reviewer === login);
66	      if (theirReview?.submittedAt) {
67	        const hours = hoursBetween(pr.createdAt, theirReview.submittedAt);
68	        if (hours >= 0) turnaroundTimes.push(hours);
69	      }
70	    }
71	    const medianReviewTurnaroundHours = median(turnaroundTimes);
72	
73	    const cleanMergeRate =
74	      prsAuthored === 0
75	        ? 0
76	        : authored.filter((p) => p.requestChangesCount === 0).length / prsAuthored;
77	
78	    const activeWeeks = new Set<number>();
79	    for (const pr of authored) {
80	      const week = Math.floor(
81	        (new Date(pr.mergedAt).getTime() - since.getTime()) / (7 * 24 * 3_600_000)
82	      );
83	      activeWeeks.add(week);
84	    }
85	    for (const pr of reviewed) {
86	      const review = pr.reviews.find((r) => r.reviewer === login);
87	      if (review?.submittedAt) {
88	        const week = Math.floor(
89	          (new Date(review.submittedAt).getTime() - since.getTime()) / (7 * 24 * 3_600_000)
90	        );
91	        activeWeeks.add(week);
92	      }
93	    }
94	    const weeklyConsistency = activeWeeks.size / totalWeeks;
95	
96	    rawMetrics.push({
97	      login,
98	      avatarUrl: avatarMap[login] ?? `https://github.com/${login}.png`,
99	      prsAuthored,
100	      prsReviewed,
101	      uniqueAuthorsReviewed,
102	      reviewCommentsGiven,
103	      medianCycleTimeHours,
104	      medianReviewTurnaroundHours,
105	      cleanMergeRate,
106	      weeklyConsistency,
107	    });
108	  }
109	
110	  const get = <K extends keyof Omit<EngineerMetrics, "scores" | "login" | "avatarUrl">>(key: K) =>
111	    rawMetrics.map((m) => m[key] as number);
112	
113	  const normActivity = normalize(rawMetrics.map((m) => m.prsAuthored + m.prsReviewed));
114	  const normPerformance = normalize(get("cleanMergeRate"));
115	  const normCollaboration = normalize(
116	    rawMetrics.map((m) => m.uniqueAuthorsReviewed + m.reviewCommentsGiven * 0.5)
117	  );
118	  const normEfficiencyCycle = normalize(get("medianCycleTimeHours"), true);
119	  const turnarounds = get("medianReviewTurnaroundHours").map((v, i) =>
120	    rawMetrics[i].prsReviewed === 0 ? Infinity : v
121	  );
122	  const normEfficiencyTurnaround = normalize(
123	    turnarounds.map((v) => (v === Infinity ? 0 : v)),
124	    true
125	  );
126	  const normEfficiency = normEfficiencyCycle.map((v, i) => (v + normEfficiencyTurnaround[i]) / 2);
127	  const normSatisfaction = normalize(get("weeklyConsistency"));
128	
129	  const results: EngineerMetrics[] = rawMetrics.map((m, i) => ({
130	    ...m,
131	    scores: {
132	      satisfaction: Math.round(normSatisfaction[i]),
133	      performance: Math.round(normPerformance[i]),
134	      activity: Math.round(normActivity[i]),
135	      collaboration: Math.round(normCollaboration[i]),
136	      efficiency: Math.round(normEfficiency[i]),
137	      composite: Math.round(
138	        (normSatisfaction[i] +
139	          normPerformance[i] +
140	          normActivity[i] +
141	          normCollaboration[i] +
142	          normEfficiency[i]) /
143	          5
144	      ),
145	    },
146	  }));
147	
148	  return results.sort((a, b) => b.scores.composite - a.scores.composite).slice(0, 5);
149	}

1	import { Octokit } from "octokit";
2	import { writeFileSync } from "fs";
3	import { join } from "path";
4	import { config } from "dotenv";
5	
6	config({ path: new URL("../.env", import.meta.url).pathname.replace(/^\/([A-Z]:)/, "$1") });
7	
8	const OWNER = "PostHog";
9	const REPO = "posthog";
10	const DAYS = 90;
11	const SINCE = new Date(Date.now() - DAYS * 24 * 60 * 60 * 1000).toISOString();
12	
13	const token = process.env.GITHUB_TOKEN;
14	if (!token) {
15	  console.error("GITHUB_TOKEN is not set — add it to .env");
16	  process.exit(1);
17	}
18	
19	const octokit = new Octokit({ auth: token });
20	
21	async function paginate<T>(fn: (page: number) => Promise<T[]>): Promise<T[]> {
22	  const results: T[] = [];
23	  let page = 1;
24	  while (true) {
25	    const batch = await fn(page);
26	    results.push(...batch);
27	    if (batch.length < 100) break;
28	    page++;
29	  }
30	  return results;
31	}
32	
33	async function main() {
34	  console.log(`Fetching data since ${SINCE} ...`);
35	
36	  // 1. Fetch all merged PRs in the window
37	  console.log("Fetching merged PRs...");
38	  // Sort by created desc so we can stop once created_at falls before SINCE.
39	  // Sorting by "updated" is unreliable — old PRs resurface when bots comment on them.
40	  const allPRs = await paginate(async (page) => {
41	    const { data } = await octokit.rest.pulls.list({
42	      owner: OWNER,
43	      repo: REPO,
44	      state: "closed",
45	      sort: "created",
46	      direction: "desc",
47	      per_page: 100,
48	      page,
49	    });
50	    const inWindow = data.filter((pr) => pr.merged_at && pr.merged_at >= SINCE);
51	    // Stop once the oldest PR on this page was created before our window
52	    const oldest = data[data.length - 1];
53	    if (oldest && oldest.created_at < SINCE) return inWindow;
54	    return inWindow;
55	  });
56	
57	  console.log(`Found ${allPRs.length} merged PRs`);
58	
59	  // 2. For each PR fetch reviews + full stats
60	  const prDetails: {
61	    number: number;
62	    author: string;
63	    authorAvatar: string;
64	    title: string;
65	    mergedAt: string;
66	    createdAt: string;
67	    additions: number;
68	    deletions: number;
69	    changedFiles: number;
70	    labels: string[];
71	    reviews: { reviewer: string; state: string; submittedAt: string }[];
72	    reviewCommentCount: number;
73	    requestChangesCount: number;
74	  }[] = [];
75	
76	  for (let i = 0; i < allPRs.length; i++) {
77	    const pr = allPRs[i];
78	    if (!pr.user || pr.user.type === "Bot") continue;
79	
80	    if (i % 20 === 0) console.log(`  Processing PR ${i + 1}/${allPRs.length}...`);
81	
82	    const [{ data: reviews }, { data: prFull }] = await Promise.all([
83	      octokit.rest.pulls.listReviews({ owner: OWNER, repo: REPO, pull_number: pr.number }),
84	      octokit.rest.pulls.get({ owner: OWNER, repo: REPO, pull_number: pr.number }),
85	    ]);
86	
87	    const filteredReviews = reviews
88	      .filter((r) => r.user && r.user.type !== "Bot" && r.user.login !== pr.user!.login)
89	      .map((r) => ({
90	        reviewer: r.user!.login,
91	        state: r.state,
92	        submittedAt: r.submitted_at ?? "",
93	      }));
94	
95	    prDetails.push({
96	      number: pr.number,
97	      author: pr.user.login,
98	      authorAvatar: pr.user.avatar_url,
99	      title: pr.title,
100	      mergedAt: pr.merged_at!,
101	      createdAt: pr.created_at,
102	      additions: prFull.additions,
103	      deletions: prFull.deletions,
104	      changedFiles: prFull.changed_files,
105	      labels: pr.labels.map((l) => l.name),
106	      reviews: filteredReviews,
107	      reviewCommentCount: prFull.review_comments,
108	      requestChangesCount: filteredReviews.filter((r) => r.state === "CHANGES_REQUESTED").length,
109	    });
110	  }
111	
112	  // 3. Fetch closed issues in window (assignee as proxy for closer)
113	  console.log("Fetching closed issues...");
114	  const issues = await paginate(async (page) => {
115	    const { data } = await octokit.rest.issues.listForRepo({
116	      owner: OWNER,
117	      repo: REPO,
118	      state: "closed",
119	      since: SINCE,
120	      per_page: 100,
121	      page,
122	    });
123	    return data.filter(
124	      (issue) =>
125	        !issue.pull_request &&
126	        issue.user?.type !== "Bot" &&
127	        issue.closed_at &&
128	        issue.closed_at >= SINCE
129	    );
130	  });
131	
132	  const issuesByCloser: Record<string, number> = {};
133	  for (const issue of issues) {
134	    if (issue.assignee && issue.assignee.type !== "Bot") {
135	      issuesByCloser[issue.assignee.login] = (issuesByCloser[issue.assignee.login] ?? 0) + 1;
136	    }
137	  }
138	
139	  const output = {
140	    fetchedAt: new Date().toISOString(),
141	    since: SINCE,
142	    prDetails,
143	    issuesByCloser,
144	  };
145	
146	  const outPath = join(
147	    new URL(".", import.meta.url).pathname.replace(/^\/([A-Z]:)/, "$1"),
148	    "../src/data/github-data.json"
149	  );
150	  writeFileSync(outPath, JSON.stringify(output, null, 2));
151	  console.log(`\nDone. Wrote ${prDetails.length} PRs to ${outPath}`);
152	}
153	
154	main().catch((err) => {
155	  console.error(err);
156	  process.exit(1);
157	});

