1	import rawData from "src/data/github-data.json";
2	import type { PRDetail, EngineerMetrics } from "src/types";
3	import { median, hoursBetween, normalize } from "src/utils";
4	
5	export const computeRankings = (): EngineerMetrics[] => {
6	  const prs = rawData.prDetails as PRDetail[];
7	
8	  const reviewedPRs: Record<string, PRDetail[]> = {};
9	  for (const pr of prs) {
10	    for (const review of pr.reviews) {
11	      if (!reviewedPRs[review.reviewer]) reviewedPRs[review.reviewer] = [];
12	      reviewedPRs[review.reviewer].push(pr);
13	    }
14	  }
15	
16	  const allLogins = new Set([...prs.map((p) => p.author), ...Object.keys(reviewedPRs)]);
17	
18	  const avatarMap: Record<string, string> = {};
19	  for (const pr of prs) avatarMap[pr.author] = pr.authorAvatar;
20	
21	  const since = new Date(rawData.since);
22	  const now = new Date(rawData.fetchedAt);
23	  const totalWeeks = Math.ceil((now.getTime() - since.getTime()) / (7 * 24 * 3_600_000));
24	
25	  const rawMetrics: Omit<EngineerMetrics, "scores">[] = [];
26	
27	  for (const login of allLogins) {
28	    const authored = prs.filter((p) => p.author === login);
29	    const reviewed = reviewedPRs[login] ?? [];
30	
31	    const prsAuthored = authored.length;
32	    const prsReviewed = reviewed.length;
33	
34	    const uniqueAuthorsReviewed = new Set(reviewed.map((p) => p.author)).size;
35	    const reviewCommentsGiven = reviewed.reduce(
36	      (sum, pr) => sum + pr.reviews.filter((r) => r.reviewer === login).length,
37	      0
38	    );
39	
40	    const medianCycleTimeHours = median(authored.map((p) => hoursBetween(p.createdAt, p.mergedAt)));
41	
42	    const turnaroundTimes: number[] = [];
43	    for (const pr of reviewed) {
44	      const theirReview = pr.reviews.find((r) => r.reviewer === login);
45	      if (theirReview?.submittedAt) {
46	        const hours = hoursBetween(pr.createdAt, theirReview.submittedAt);
47	        if (hours >= 0) turnaroundTimes.push(hours);
48	      }
49	    }
50	    const medianReviewTurnaroundHours = median(turnaroundTimes);
51	
52	    const cleanMergeRate =
53	      prsAuthored === 0
54	        ? 0
55	        : authored.filter((p) => p.requestChangesCount === 0).length / prsAuthored;
56	
57	    const activeWeeks = new Set<number>();
58	    for (const pr of authored) {
59	      activeWeeks.add(
60	        Math.floor((new Date(pr.mergedAt).getTime() - since.getTime()) / (7 * 24 * 3_600_000))
61	      );
62	    }
63	    for (const pr of reviewed) {
64	      const review = pr.reviews.find((r) => r.reviewer === login);
65	      if (review?.submittedAt) {
66	        activeWeeks.add(
67	          Math.floor(
68	            (new Date(review.submittedAt).getTime() - since.getTime()) / (7 * 24 * 3_600_000)
69	          )
70	        );
71	      }
72	    }
73	    const weeklyConsistency = activeWeeks.size / totalWeeks;
74	
75	    rawMetrics.push({
76	      login,
77	      avatarUrl: avatarMap[login] ?? `https://github.com/${login}.png`,
78	      prsAuthored,
79	      prsReviewed,
80	      uniqueAuthorsReviewed,
81	      reviewCommentsGiven,
82	      medianCycleTimeHours,
83	      medianReviewTurnaroundHours,
84	      cleanMergeRate,
85	      weeklyConsistency,
86	    });
87	  }
88	
89	  const get = <K extends keyof Omit<EngineerMetrics, "scores" | "login" | "avatarUrl">>(key: K) =>
90	    rawMetrics.map((m) => m[key] as number);
91	
92	  const normActivity = normalize(rawMetrics.map((m) => m.prsAuthored + m.prsReviewed));
93	  const normPerformance = normalize(get("cleanMergeRate"));
94	  const normCollaboration = normalize(
95	    rawMetrics.map((m) => m.uniqueAuthorsReviewed + m.reviewCommentsGiven * 0.5)
96	  );
97	  const normEfficiencyCycle = normalize(get("medianCycleTimeHours"), true);
98	  const normEfficiencyTurnaround = normalize(
99	    get("medianReviewTurnaroundHours").map((v, i) => (rawMetrics[i].prsReviewed === 0 ? 0 : v)),
100	    true
101	  );
102	  const normEfficiency = normEfficiencyCycle.map((v, i) => (v + normEfficiencyTurnaround[i]) / 2);
103	  const normSatisfaction = normalize(get("weeklyConsistency"));
104	
105	  const results: EngineerMetrics[] = rawMetrics.map((m, i) => ({
106	    ...m,
107	    scores: {
108	      satisfaction: Math.round(normSatisfaction[i]),
109	      performance: Math.round(normPerformance[i]),
110	      activity: Math.round(normActivity[i]),
111	      collaboration: Math.round(normCollaboration[i]),
112	      efficiency: Math.round(normEfficiency[i]),
113	      composite: Math.round(
114	        (normSatisfaction[i] +
115	          normPerformance[i] +
116	          normActivity[i] +
117	          normCollaboration[i] +
118	          normEfficiency[i]) /
119	          5
120	      ),
121	    },
122	  }));
123	
124	  return results.sort((a, b) => b.scores.composite - a.scores.composite).slice(0, 5);
125	};

