1	import { Octokit } from "octokit";
2	import { writeFileSync } from "fs";
3	import { join } from "path";
4	import { config } from "dotenv";
5	
6	config({ path: new URL("../.env", import.meta.url).pathname.replace(/^\/([A-Z]:)/, "$1") });
7	
8	const OWNER = "PostHog";
9	const REPO = "posthog";
10	const DAYS = 90;
11	const SINCE = new Date(Date.now() - DAYS * 24 * 60 * 60 * 1000).toISOString();
12	
13	const token = process.env.GITHUB_TOKEN;
14	if (!token) {
15	  console.error("GITHUB_TOKEN is not set — add it to .env");
16	  process.exit(1);
17	}
18	
19	const octokit = new Octokit({ auth: token });
20	
21	const paginate = async <T>(fn: (page: number) => Promise<T[]>): Promise<T[]> => {
22	  const results: T[] = [];
23	  let page = 1;
24	  while (true) {
25	    const batch = await fn(page);
26	    results.push(...batch);
27	    if (batch.length < 100) break;
28	    page++;
29	  }
30	  return results;
31	};
32	
33	const main = async () => {
34	  console.log(`Fetching data since ${SINCE} ...`);
35	
36	  // 1. Fetch all merged PRs in the window
37	  console.log("Fetching merged PRs...");
38	  // Sort by created desc so we can stop once created_at falls before SINCE.
39	  // Sorting by "updated" is unreliable — old PRs resurface when bots comment on them.
40	  const allPRs = await paginate(async (page) => {
41	    const { data } = await octokit.rest.pulls.list({
42	      owner: OWNER,
43	      repo: REPO,
44	      state: "closed",
45	      sort: "created",
46	      direction: "desc",
47	      per_page: 100,
48	      page,
49	    });
50	    const inWindow = data.filter((pr) => pr.merged_at && pr.merged_at >= SINCE);
51	    // Stop once the oldest PR on this page was created before our window
52	    const oldest = data[data.length - 1];
53	    if (oldest && oldest.created_at < SINCE) return inWindow;
54	    return inWindow;
55	  });
56	
57	  console.log(`Found ${allPRs.length} merged PRs`);
58	
59	  // 2. For each PR fetch reviews + full stats
60	  const prDetails: {
61	    number: number;
62	    author: string;
63	    authorAvatar: string;
64	    title: string;
65	    mergedAt: string;
66	    createdAt: string;
67	    additions: number;
68	    deletions: number;
69	    changedFiles: number;
70	    labels: string[];
71	    reviews: { reviewer: string; state: string; submittedAt: string }[];
72	    reviewCommentCount: number;
73	    requestChangesCount: number;
74	  }[] = [];
75	
76	  for (let i = 0; i < allPRs.length; i++) {
77	    const pr = allPRs[i];
78	    if (!pr.user || pr.user.type === "Bot") continue;
79	
80	    if (i % 20 === 0) console.log(`  Processing PR ${i + 1}/${allPRs.length}...`);
81	
82	    const [{ data: reviews }, { data: prFull }] = await Promise.all([
83	      octokit.rest.pulls.listReviews({ owner: OWNER, repo: REPO, pull_number: pr.number }),
84	      octokit.rest.pulls.get({ owner: OWNER, repo: REPO, pull_number: pr.number }),
85	    ]);
86	
87	    const filteredReviews = reviews
88	      .filter((r) => r.user && r.user.type !== "Bot" && r.user.login !== pr.user!.login)
89	      .map((r) => ({
90	        reviewer: r.user!.login,
91	        state: r.state,
92	        submittedAt: r.submitted_at ?? "",
93	      }));
94	
95	    prDetails.push({
96	      number: pr.number,
97	      author: pr.user.login,
98	      authorAvatar: pr.user.avatar_url,
99	      title: pr.title,
100	      mergedAt: pr.merged_at!,
101	      createdAt: pr.created_at,
102	      additions: prFull.additions,
103	      deletions: prFull.deletions,
104	      changedFiles: prFull.changed_files,
105	      labels: pr.labels.map((l) => l.name),
106	      reviews: filteredReviews,
107	      reviewCommentCount: prFull.review_comments,
108	      requestChangesCount: filteredReviews.filter((r) => r.state === "CHANGES_REQUESTED").length,
109	    });
110	  }
111	
112	  // 3. Fetch closed issues in window (assignee as proxy for closer)
113	  console.log("Fetching closed issues...");
114	  const issues = await paginate(async (page) => {
115	    const { data } = await octokit.rest.issues.listForRepo({
116	      owner: OWNER,
117	      repo: REPO,
118	      state: "closed",
119	      since: SINCE,
120	      per_page: 100,
121	      page,
122	    });
123	    return data.filter(
124	      (issue) =>
125	        !issue.pull_request &&
126	        issue.user?.type !== "Bot" &&
127	        issue.closed_at &&
128	        issue.closed_at >= SINCE
129	    );
130	  });
131	
132	  const issuesByCloser: Record<string, number> = {};
133	  for (const issue of issues) {
134	    if (issue.assignee && issue.assignee.type !== "Bot") {
135	      issuesByCloser[issue.assignee.login] = (issuesByCloser[issue.assignee.login] ?? 0) + 1;
136	    }
137	  }
138	
139	  const output = {
140	    fetchedAt: new Date().toISOString(),
141	    since: SINCE,
142	    prDetails,
143	    issuesByCloser,
144	  };
145	
146	  const outPath = join(
147	    new URL(".", import.meta.url).pathname.replace(/^\/([A-Z]:)/, "$1"),
148	    "../src/data/github-data.json"
149	  );
